  if (head === "przyklady" && !sub) { html = examplesPage(); title = "Przykłady: Logomocja"; markNav("#/przyklady"); }
  else if (head === "zadania" && !sub) { html = challengesPage(); title = "Zadania: Logomocja"; markNav("#/zadania"); }
