:root {
  color-scheme: light;
  --desk: #e8ecf2;
  --pane: #f4f6f9;
  --sheet: #fdfdfb;
  --sheet-grid: #e9edf3;
  --sheet-grid-strong: #d3dbe7;
  --ink: #14213d;
  --ink-soft: #4d5b78;
  --rule-soft: #c3cbd9;
  --shell: #1d3f8a;
  --shell-ink: #ffffff;
  --shell-soft: #d3ddf5;
  --turtle: #0f7a5f;
  --turtle-hover: #0b6650;
  --on-turtle: #ffffff;
  --turtle-mark: #16866a;
  --turtle-tint: #d9eee6;
  --error: #b3261e;
  --error-solid: #b3261e;
  --on-error: #ffffff;
  --error-tint: #fbe6e3;
  --warn: #7a4a00;
  --tint: #e2e8f1;
  --select: rgba(29, 63, 138, 0.2);
  --focus: #1d3f8a;
  --backdrop: rgba(20, 33, 61, 0.5);
  --t-cmd: #1d3f8a;
  --t-num: #8a4b00;
  --t-str: #0d6b54;
  --t-com: #5c6880;
  --t-br: #7a2e8e;
