  --font-ui: "Public Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-draw: "osifont", "Public Sans", system-ui, sans-serif;
  --font-code: "Red Hat Mono", ui-monospace, "Cascadia Mono", Menlo, Consolas, monospace;
  --fs-xs: 0.75rem;
  --fs-s: 0.8125rem;
  --fs-m: 0.9375rem;
  --fs-l: 1.25rem;
  --fs-xl: 1.5rem;
  --fs-xxl: 2.25rem;
  --line-thin: 1px;
  --line-mid: 2px;
  --line-thick: 3px;
  --r: 2px;
  --top-h: 3rem;
  --ctl: 2.25rem;
  --ed-pad: 12px;
  --ed-fs: 0.875rem;
  --ed-lh: 22px;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --desk: #070c16;
  --pane: #0f1829;
  --sheet: #0c1320;
  --sheet-grid: #141d31;
  --sheet-grid-strong: #212e4c;
  --ink: #e4eaf5;
  --ink-soft: #9aaac6;
  --rule-soft: #2c3b5c;
  --shell: #15306f;
  --shell-ink: #ffffff;
  --shell-soft: #c5d2f2;
  --turtle: #3cc49a;
  --turtle-hover: #5fd6b0;
  --on-turtle: #04211a;
  --turtle-mark: #2fb48d;
  --turtle-tint: #133a30;
