await ta.focus(); await p.keyboard.press('Control+End'); await p.keyboard.type('np 5');
await p.waitForTimeout(200);
console.log('edit while running:', await st(), '| seg', await tb('seg'));
// lint
await ta.fill('np 100\nnp\npw 90'); await p.waitForTimeout(900);
console.log('lint:', await st(), '| bubble:', await p.locator('.ed-bubble').textContent(), '| gutter err:', await p.locator('.ed-gutter .is-error').textContent().catch(() => null));
await p.click('.runbar [data-act="run"]'); await p.waitForTimeout(200);
ok('parse error draws nothing', (await tb('seg')).trim().startsWith('0'), await tb('seg'));
// reload persistence
